  50: "آغاز حرف قٓ اور قرآنِ مجید کی قسم سے۔ قیامت کے لیے مکی دلیل: اللہ جس نے آسمان بنائے اور نفس کی ہر سرگوشی جانتا ہے، وہ یقیناً مردوں کو اٹھا سکتا ہے۔",
  51: "آغاز بکھیرنے والی ہواؤں کی قسم سے۔ ابراہیم کے معزز مہمانوں، جھٹلانے والی قوموں کی تباہی کا ذکر، اور نصیحت کا حکم — اور نصیحت کرو، بے شک نصیحت مومنوں کو فائدہ دیتی ہے۔",
  52: "کوہِ طور اور بیت المعمور (آباد گھر) کی قسم۔ مکی سورت اس دن سے ڈراتی ہے جب آسمان ہلنے لگے گا، اور اثبات کرتی ہے کہ نبی نہ کاہن ہیں نہ مجنون، بلکہ منذر ہیں۔",
  53: "ستارے کی قسم جب وہ گرتا ہے۔ مکہ میں سجدے کے ساتھ علانیہ پڑھی جانے والی پہلی سورت — مشرک بھی سن کر سجدے میں گر پڑے۔ نبی کے معراج اور موصولہ وحی کا دفاع۔",
  54: "قیامت قریب آ گئی اور چاند پھٹ گیا — مکہ والوں نے چاند پھٹتا دیکھا پھر بھی جادو کہا۔ ہر تباہ قوم کے بعد اس کا نغمہ: اور ہم نے قرآن کو نصیحت کے لیے آسان کر دیا۔",
  55: "الٰہی نعمتوں کی سمفنی: تم اپنے رب کی کون کون سی نعمتیں جھٹلاؤ گے؟ — تخلیق، دو سمندروں اور متقیوں سے وعدہ کردہ باغات کی نعمتوں پر اکتیس بار دہرایا گیا۔",
  56: "آنے والی حتمی گھڑی (واقعہ) — قیامت — انسانیت کو تین گروہوں میں بانٹنے والی: سبقت لے جانے والے، دائیں والے، بائیں والے؛ ہر گروہ کے انجام کی واضح تصویر۔",
  57: "نام لوہے (حدید) سے، جس میں سخت قوت اور لوگوں کے لیے فائدے ہیں۔ موت سے پہلے اللہ کی راہ میں خرچ کی مدنی دعوت؛ آخری دن مومنوں کے نور بمقابلہ منافقین کی تاریکی کا تقابل۔",
  58: "اللہ نے اس عورت کی فریاد سن لی جو اپنے شوہر کے بارے میں جھگڑ رہی تھی — خولہ، جن کی شکایت نے زمانۂ جاہلیت کی ظہار کی رسم ختم کر دی۔ نجی مشورے سے پہلے صدقے کے احکام اور گناہ کی سرگوشیوں کی مذمت۔",
  59: "بنو نضیر کی جلاوطنی پر۔ اس کی آخری آیات — قرآن میں سب سے زیادہ پڑھی جانے والی آیات میں سے — اللہ کے اسمائے حسنیٰ گنتی ہیں: بادشاہ، پاک، سلامتی دینے والا، زبردست۔",
  60: "مدینہ ہجرت کرنے والی مومن عورتوں کے ایمان کے امتحان کا حکم، اور اللہ کے دشمنوں سے دوستی کی ممانعت — جبکہ پرامن غیر مسلموں سے حسنِ سلوک اور عدل کی اجازت۔",
  61: "اللہ ان سے محبت کرتا ہے جو اس کی راہ میں مضبوط صفوں میں جدوجہد کرتے ہیں۔ موسیٰ اور عیسیٰ کا ذکر — عیسیٰ نے احمد نام کے رسول کی بشارت دی — اور دردناک عذاب سے بچانے والی تجارت: ایمان اور جدوجہد۔",
  62: "جمعہ کی باجماعت نماز قائم کرتی ہے: اللہ کے ذکر کی طرف دوڑو اور تجارت چھوڑ دو۔ ان کی سرزنش جنہیں تورات سونپی گئی پھر اسے ایسے اٹھائے جیسے گدھے کتابیں لادے ہوں۔",
  63: "مدینہ کے منافقین کا پردہ فاش — ان کی جھوٹی قسمیں، ان کا مذاق، شہر سے معززوں کو نکالنے کا ان کا دعویٰ — اور مومنوں کو تنبیہ کہ مال و اولاد انہیں ذکر سے غافل نہ کریں۔",
  64: "ہار جیت کا دن (تغابن) جب دھوکہ کھانے والے اور دھوکہ دینے والے آمنے سامنے ہوں گے۔ ایمان، اطاعت اور صدقے کی دعوت؛ مال و اولاد محض آزمائش ہیں۔",
  65: "طلاق کے احکام کی سورت: عدت، نان نفقہ اور مطلقہ عورتوں کی رہائش — اس یاددہانی کے ساتھ کہ اللہ متقی کو وہاں سے رزق دیتا ہے جہاں سے اسے گمان نہ ہو۔",
  66: "نازل ہوئی جب نبی نے بیویوں کی رضا کے لیے اپنے اوپر حلال چیز حرام کر لی — تم اللہ کی حلال کی ہوئی چیز کیوں حرام کرتے ہو؟ اختتام مومن عورتوں کی مثالوں پر: مریم اور فرعون کی بیوی۔",
  67: "بابرکت ہے وہ جس کے ہاتھ میں بادشاہی ہے۔ نبوی روایت کے مطابق رات کو پڑھی جانے والی سورت؛ تخلیق پر اللہ کی مطلق بادشاہی کا اعلان اور منکروں کے لیے عذاب کی تنبیہ۔",
  68: "قلم اور جو کچھ وہ لکھتے ہیں اس کی قسم۔ نبی کا دفاع — بے شک آپ عظیم اخلاق پر ہیں — جنون کے الزام کے مقابل، اور باغ والوں کی مثال سے مکہ کے سرداروں کو تنبیہ۔",
  69: "اٹل حقیقت (حاقہ)۔ ثمود، عاد اور فرعون کے منظرنامے جو انکار پر تباہ ہوئے؛ حساب اور اعمال کے تولے جانے کا اثبات — قیامت کے منکروں پر مکی گرج۔",
  70: "وہ سیڑھیاں (معارج) جن سے فرشتے چڑھتے ہیں۔ مکی تنبیہ کہ مذاق اڑانے والے جس عذاب کا مطالبہ کرتے ہیں وہ ضرور آئے گا، اور انسانی بے صبری کی تصویر — جس کا علاج صرف نماز، صدقہ اور یقین ہے۔",
  71: "پوری سورت نوح کی ساڑھے نو سو سالہ دعوت ہے: ان کی علانیہ و پوشیدہ تبلیغ، ان کی قوم کی بہرہ پنی اور تکبر، اور ان کی آخری دعا — مکہ میں نبی کے اپنے صبر کا آئینہ۔",
  72: "جنوں کی ایک جماعت نے قرآن سنا، ایمان لائی اور منذر بن کر اپنی قوم کی طرف لوٹی۔ مکی سورت غیب کی دنیا کا اثبات کرتی ہے اور اعلان کرتی ہے کہ ہدایت انسانوں سے آگے پہنچتی ہے۔",
  73: "ابتدائی وحیوں میں سے: اے چادر اوڑھنے والے، رات کو قیام کر۔ رات کی عبادت اور ٹھہر ٹھہر کر تلاوت کا حکم، آنے والے بھاری کلام کی تیاری کے طور پر۔",
  74: "اے چادر اوڑھنے والے، اٹھ اور ڈرا! — دعوت کے پہلے احکام میں سے۔ طہارت، صبر اور بتوں سے دوری کا حکم، اور اس دن کی تنبیہ جب صور پھونکا جائے گا۔",
  75: "قیامت کے دن اور ملامت کرنے والی جان کی قسم۔ قیامت کا دن کب ہے؟ پوچھنے والا منکر دیکھے گا کہ ہڈیاں جوڑ دی جائیں گی — اللہ انگلیوں کے پور تک بنا سکتا ہے۔",
  76: "الدہر بھی کہلاتی ہے۔ انسان کی نطفے کے قطرے سے تخلیق پر مدنی غور؛ نیک لوگ جو مسکین، یتیم اور قیدی کو صرف اللہ کے لیے کھلاتے ہیں، اور ان کے منتظر جنت۔",
  77: "پے در پے بھیجی جانے والی ہواؤں (مرسلات) کی قسم۔ اس کا ہتھوڑے جیسا نغمہ — اس دن جھٹلانے والوں کے لیے ویل! — حساب کے مناظر اور پچھلی قوموں کے انجام سے دس بار دہرایا گیا۔",
  78: "وہ کس چیز کے بارے میں ایک دوسرے سے پوچھتے ہیں؟ بڑی خبر کے بارے میں۔ مکی سورت قرآن کے آخری حصے کا آغاز قیامت کے یقین، حساب اور نقصان اٹھانے والوں کے پچھتاوے سے کرتی ہے۔",
  79: "نرمی یا سختی سے روحیں نکالنے والے فرشتوں (نازعات) کی قسم۔ موسیٰ کی فرعون کی طرف دعوت کا ذکر — جس نے کہا میں تمہارا سب سے بڑا رب ہوں — اور اس کا غرق ہونا؛ مکہ کے سرداروں کو تنبیہ۔",
  80: "انہوں نے تیوری چڑھائی اور منہ موڑ لیا جب نابینا آیا۔ نبی کی نرمی سے اصلاح کہ سرداروں کو مخلص طالب ابنِ ام مکتوم پر ترجیح دی — ہر مومن کی قدر کا لازوال سبق۔",
  81: "جب سورج لپیٹ دیا جائے اور ستارے جھڑ جائیں۔ آخری دن کی کائناتی الٹ پھیر، اور قرآن کا دفاع کہ وہ معزز رسول کا کلام ہے — کسی مجنون یا شاعر کی بات نہیں۔",
  82: "جب آسمان پھٹ جائے اور قبریں الٹ دی جائیں۔ انسان کی ناشکری پر مختصر مکی سورت: تجھے تیرے کریم رب کے بارے میں کس نے دھوکے میں ڈالا؟",
  83: "ناپ تول میں کمی کرنے والوں (مطففین) کے لیے ویل — لیتے وقت پورا مانگتے ہیں، دیتے وقت کم دیتے ہیں۔ ان کا نامۂ اعمال سجّین میں؛ نیک لوگ علّیین میں نعمتوں کا مشاہدہ کریں گے۔",
  84: "جب آسمان پھٹ جائے اور زمین اپنا بوجھ نکال پھینکے۔ انسان اپنے رب کی طرف محنت کرتا ہوا اس سے ملے گا — اپنا نامۂ اعمال دائیں ہاتھ میں پائے گا، یا پیٹھ کے پیچھے سے۔",
  85: "بڑے برجوں والے آسمان کی قسم۔ خندق والوں (اصحاب الاخدود) کی یاد — ظالم بادشاہ کے ہاتھوں زندہ جلائے گئے مومن — مکہ کے ستائے گئے مسلمانوں کی تسلی کہ ظالم آخرکار کبھی کامیاب نہیں ہوتے۔",
  86: "رات کو چمکنے والے تیز ستارے (طارق) کی قسم۔ ہر جان پر ایک نگہبان ہے؛ اللہ جس نے انسان کو اچھلتے پانی سے پیدا کیا وہ اسے دوبارہ زندہ کر سکتا ہے — اور قرآن فیصلہ کن کلام ہے، مذاق نہیں۔",
  87: "اپنے بلند رب کے نام کی تسبیح کرو۔ دونوں عیدوں اور وتر میں نبی کی محبوب سورت؛ کامیابی کا وعدہ اس کے لیے جو پاک ہوا اور اپنے رب کو یاد کیا۔",
  88: "کیا تجھے چھا جانے والی (غاشیہ) کی خبر پہنچی؟ اس دن چہرے ذلیل اور چہرے روشن — پھر اونٹ، آسمان، پہاڑوں اور بچھائی ہوئی زمین پر غور کی دعوت۔",
  89: "فجر اور دس راتوں کی قسم۔ عاد، ثمود اور فرعون کا ذکر؛ اور بے قرار نفس کو تنبیہ — سکون صرف اپنے رب کی طرف لوٹنے میں ہے، راضی اور مرضی۔",
  90: "اس شہر (بلد) — مکہ — کی قسم جبکہ نبی اس میں مقیم ہیں۔ چڑھائی کا کٹھن راستہ: غلام آزاد کرنا اور قحط کے دن بھوکے کو کھلانا — شکر اور ناشکری میں سے انتخاب۔",
  91: "سورج اور اس کی روشنی کی قسم۔ نفس کو اس کی بدی اور تقویٰ دونوں کا الہام ہوا — کامیاب ہوا جس نے اسے پاک کیا۔ ثمود کی اونٹنی کی ٹانگیں کاٹنے کا واقعہ تنبیہ پر مہر۔",
  92: "رات کی قسم جب وہ چھا جائے۔ دو راستے جدا: سخی متقی دینے والا آسانی کی طرف لے جایا جاتا ہے، جبکہ بخیل جھٹلانے والا تنگی کی طرف۔",
  93: "وحی میں وقفے کے بعد نبی کی تسلی کے لیے نازل ہوئی: تیرے رب نے تجھے چھوڑا نہیں اور نہ وہ ناراض ہے۔ رات کے بعد صبح کی روشنی — ہر مشکل میں مومن کے لیے الٰہی عنایت کا وعدہ۔",
  94: "الم نشرح بھی کہلاتی ہے۔ کیا ہم نے تیرا سینہ تیرے لیے کھول نہیں دیا؟ — ہر تنگی کے ساتھ آسانی ہے، دو بار تاکید۔ ہر دبے دل کی تسلی کا مکی وعدہ۔",
  95: "انجیر اور زیتون، کوہِ طور اور اس امن والے شہر کی قسم۔ انسان احسن تقویم میں پیدا کیا گیا — پھر پست ترین میں لوٹا دیا گیا، سوائے ان کے جو ایمان لائے اور نیک عمل کیے۔",
  96: "پہلی وحی: پڑھ! اپنے رب کے نام سے جس نے پیدا کیا — انسان کو جمے ہوئے خون سے پیدا کیا۔ نماز سے روکنے والے سرکش کی سرزنش اور اختتام اس حکم پر: سجدہ کر اور قریب ہو۔",
  97: "شبِ قدر ہزار مہینوں سے بہتر ہے — وہ رات جس میں قرآن نازل ہوا، جب فرشتے اور روح ہر حکم لے کر اترتے ہیں، طلوعِ فجر تک سلامتی۔",
  98: "مدنی سورت: اہلِ کتاب اور مشرکین واضح دلیل (بینہ) — پاک صحیفے پڑھنے والا رسول — آنے تک باز نہ آئے۔ سچا دین: اخلاص سے عبادت، نماز اور زکاۃ۔",
  99: "جب زمین زور سے ہلا دی جائے اور اپنے بوجھ نکال پھینکے۔ جو ذرہ برابر نیکی کرے گا اسے دیکھ لے گا — مکمل، ناگزیر حساب کی مدنی تنبیہ۔",
  100: "ہانپتے دوڑتے، آگ کی چنگاریاں اڑاتے گھوڑوں (عادیات) کی قسم۔ انسان اپنے رب کا ناشکرا ہے اور مال کی محبت میں سخت — لیکن اس دن سینوں کا حال کھول دیا جائے گا۔",
  101: "کھڑکھڑانے والی (قارعہ)! لوگ بکھرے پروانوں جیسے، پہاڑ دھنکی ہوئی اون جیسے۔ بھاری پلڑے تو خوشگوار زندگی؛ ہلکے تو دہکتی گڑھا۔",
  102: "دنیاوی کثرت کی دوڑ تمہیں غافل رکھتی ہے یہاں تک کہ تم قبروں میں جا پہنچو۔ تم ضرور دوزخ کو یقین کی آنکھ سے دیکھو گے — پھر ہر نعمت کا سوال ہوگا۔",
  103: "زمانے (عصر) کی قسم، انسان خسارے میں ہے — سوائے ان کے جو ایمان لائے، نیک عمل کیے، حق کی وصیت کی اور صبر کی وصیت کی۔ امام شافعی نے کہا یہ مختصر سورت انسانیت کے لیے کافی ہوتی۔",
  104: "ہر طعنہ زن، عیب جو کے لیے ویل جو مال جمع کرتا ہے اور سمجھتا ہے کہ وہ اسے ہمیشہ رکھے گا۔ اس کا انجام: دلوں کو چیرنے والی دہکتی آگ۔",
  105: "اللہ نے ہاتھی والوں سے کیا سلوک کیا — نبی کی پیدائش کے سال کعبہ پر چڑھ آنے والا ابرہہ کا لشکر، پکی مٹی کے پتھر برسانے والے پرندوں کے جھنڈوں سے تباہ۔",
  106: "قریش کے مانوس امن کے لیے — ان کے سردی اور گرمی کے تجارتی سفر۔ سو انہیں اس گھر کے رب کی عبادت کرنی چاہیے، جس نے انہیں بھوک سے کھلایا اور خوف سے امن دیا۔",
  107: "جزا کو جھٹلانے والے: یتیم کو دھکارتے ہیں، مسکین کو کھلانے کی ترغیب نہیں دیتے، نماز میں غافل ہیں، دکھاوا کرتے ہیں، اور چھوٹی سے چھوٹی بھلائی بھی روک لیتے ہیں۔",
  108: "سب سے چھوٹی سورت: بے شک ہم نے تمہیں کوثر عطا کی۔ سو اپنے رب کے لیے نماز پڑھو اور قربانی کرو — تمہارا دشمن ہی کٹا ہوا ہے، تم نہیں۔",
  109: "براءت کی سورت: اے کافرو! میں اس کی عبادت نہیں کرتا جس کی تم عبادت کرتے ہو... تمہارا دین تمہارے لیے، میرا دین میرے لیے۔ نبی اسے فجر و مغرب کی سنت نمازوں میں باقاعدگی سے پڑھتے تھے۔",
  110: "مکمل نازل ہونے والی آخری سورت۔ جب اللہ کی مدد آئے اور لوگ دین میں جوق در جوق داخل ہوں — اپنے رب کی حمد کے ساتھ تسبیح کرو اور اس سے بخشش مانگو۔ حجۃ الوداع کے قریب نازل ہوئی۔",
  111: "اللہب بھی کہلاتی ہے۔ ابو لہب اور اس کی بیوی، ایندھن اٹھانے والی — جس کی گردن میں کھجور کی رسی ہوگی — کی مذمت۔ مکہ کے سخت ظلم کے دور میں نازل ہوئی۔",
  112: "خالص توحید کی سورت: کہو: وہ اللہ ایک ہے۔ نبی نے فرمایا یہ قرآن کے ایک تہائی کے برابر ہے — چار آیتیں جو اللہ کو ہر مشابہت اور حاجت سے پاک بیان کرتی ہیں۔",
  113: "الناس کے ساتھ پناہ کی دو سورتوں میں سے ایک۔ صبح کے رب کی پناہ: رات کی تاریکی، گرہوں میں پھونکنے والوں، اور حاسد کے حسد کے شر سے۔",
  114: "قرآن کی آخری سورت: انسانوں کے رب، بادشاہ اور معبود کی پناہ پیچھے ہٹنے والے وسوسہ ڈالنے والے سے — جو لوگوں کے سینوں میں وسوسے ڈالتا ہے، جنوں اور انسانوں میں سے۔",
};
